export function lateFee(invoice, asOf) {
  if (!invoice.dueDate || invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const amountDue = balanceDue(invoice);
  const fee = roundCents(amountDue * 0.0004 * daysOverdue);

  return fee;
}

export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  for (const inv of invoices) {
    counts[inv.status]++;
  }

  let outstanding = 0;
  for (const inv of invoices) {
    if (inv.status === 'issued' || inv.status === 'partially_paid') {
      outstanding += balanceDue(inv);
    }
  }

  const overdue = overdueInvoices(invoices, asOf);
  const overdueAmount = overdue.reduce((sum, inv) => sum + inv.due, 0);

  const customerDue = {};
  for (const inv of invoices) {
    if (inv.status === 'issued' || inv.status === 'partially_paid') {
      const customerId = inv.customerId;
      if (!customerDue[customerId]) {
        customerDue[customerId] = 0;
      }
      customerDue[customerId] += balanceDue(inv);
    }
  }

  const topCustomers = Object.entries(customerDue)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue: {
      count: overdue.length,
      amount: overdueAmount,
    },
    topCustomers,
  };
}

