import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

test('overdueInvoices includes invoices with dueDate before asOf', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const overdue = overdueInvoices([issued], '2026-10-20');
  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].number, 'INV-2026-0001');
  assert.equal(overdue[0].dueDate, '2026-10-15');
});

test('overdueInvoices excludes future due dates', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const overdue = overdueInvoices([issued], '2026-10-14');
  assert.equal(overdue.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-10' }).value;

  const overdue = overdueInvoices([paid], '2026-10-20');
  assert.equal(overdue.length, 0);
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const overdue = overdueInvoices([inv], '2026-10-20');
  assert.equal(overdue.length, 0);
});

test('overdueInvoices sorts by most overdue first', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const overdue = overdueInvoices([issued2, issued1], '2026-10-25');
  assert.equal(overdue.length, 2);
  assert.equal(overdue[0].dueDate, '2026-10-15');
  assert.equal(overdue[0].daysOverdue, 10);
  assert.equal(overdue[1].dueDate, '2026-10-19');
  assert.equal(overdue[1].daysOverdue, 6);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const overdue = overdueInvoices([issued], '2026-10-25');
  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].daysOverdue, 10);
});

test('overdueInvoices includes due amount from partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const halfPayment = Math.floor(totals.total / 2);
  const partial = recordPayment(issued, { amount: halfPayment, date: '2026-10-10' }).value;

  const overdue = overdueInvoices([partial], '2026-10-20');
  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].due, totals.total - halfPayment);
});

test('overdueInvoices returns empty list when no overdue invoices', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const overdue = overdueInvoices([issued], '2026-10-15');
  assert.equal(overdue.length, 0);
});

test('overdueInvoices includes customerId in result', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const overdue = overdueInvoices([issued], '2026-10-20');
  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].customerId, 'C-003');
});

test('overdueInvoices with multiple statuses', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const totals2 = invoiceTotals(issued2);
  const partial = recordPayment(issued2, { amount: Math.floor(totals2.total / 2), date: '2026-10-10' }).value;

  const overdue = overdueInvoices([issued1, partial], '2026-10-25');
  assert.equal(overdue.length, 2);
});

test('vatSummary with single VAT rate', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert.equal(summary.length, 1);
  assert.equal(summary[0].rate, 21);
});

test('vatSummary includes multiple VAT rates', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
    ],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert.equal(summary.length, 2);
  assert(summary.some(s => s.rate === 21));
  assert(summary.some(s => s.rate === 9));
});

test('vatSummary sorts by rate descending', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert.equal(summary[0].rate, 21);
  assert.equal(summary[1].rate, 9);
});

test('vatSummary excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const summary = vatSummary([inv]);
  assert.equal(summary.length, 0);
});

test('vatSummary includes issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert.equal(summary.length, 1);
});

test('vatSummary includes partially paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partial = recordPayment(issued, { amount: Math.floor(totals.total / 2), date: '2026-10-05' }).value;

  const summary = vatSummary([partial]);
  assert.equal(summary.length, 1);
});

test('vatSummary includes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-05' }).value;

  const summary = vatSummary([paid]);
  assert.equal(summary.length, 1);
});

test('vatSummary calculates base correctly with discount', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert.equal(summary.length, 1);
  const lineTotal = 10 * 8500;
  const firstDiscount = lineTotal * 10 / 100;
  const afterFirst = lineTotal - firstDiscount;
  const bulkDiscount = afterFirst * 2.5 / 100;
  const expectedBase = lineTotal - firstDiscount - bulkDiscount;
  assert.equal(summary[0].base, Math.round(expectedBase));
});

test('vatSummary sums multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const summary = vatSummary([issued1, issued2]);
  assert.equal(summary.length, 1);
  const singleVAT = summary[0].vat;
  assert(singleVAT > 0);
});

test('vatSummary with VAT-exempt items', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert(summary.some(s => s.rate === 0));
  assert(summary.some(s => s.rate === 21));
});

test('vatSummary returns empty list for no matching invoices', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const summary = vatSummary([inv]);
  assert.equal(summary.length, 0);
});

test('lateFee returns 0 when invoice is not overdue', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const fee = lateFee(issued, '2026-10-15');
  assert.equal(fee, 0);
});

test('lateFee returns 0 when invoice is due on asOf', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const fee = lateFee(issued, '2026-10-15');
  assert.equal(fee, 0);
});

test('lateFee calculates fee for overdue invoice', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const fee = lateFee(issued, '2026-10-20');
  const expectedFee = Math.round(totals.total * 0.0004 * 5);
  assert.equal(fee, expectedFee);
});

test('lateFee charges on amount still due', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const halfPayment = Math.floor(totals.total / 2);
  const partial = recordPayment(issued, { amount: halfPayment, date: '2026-10-10' }).value;

  const fee = lateFee(partial, '2026-10-20');
  const amountDue = totals.total - halfPayment;
  const expectedFee = Math.round(amountDue * 0.0004 * 5);
  assert.equal(fee, expectedFee);
});

test('lateFee returns 0 for paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-10' }).value;

  const fee = lateFee(paid, '2026-10-25');
  assert.equal(fee, 0);
});

test('lateFee scales with days overdue', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const fee10Days = lateFee(issued, '2026-10-25');
  const fee5Days = lateFee(issued, '2026-10-20');

  const expectedFee10 = Math.round(totals.total * 0.0004 * 10);
  const expectedFee5 = Math.round(totals.total * 0.0004 * 5);
  assert.equal(fee10Days, expectedFee10);
  assert.equal(fee5Days, expectedFee5);
