test('vatSummary with single VAT rate', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert.equal(summary.length, 1);
  assert.equal(summary[0].rate, 21);
});

test('vatSummary includes multiple VAT rates', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
    ],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert.equal(summary.length, 2);
  assert(summary.some(s => s.rate === 21));
