test('vatSummary calculates base correctly with discount', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const summary = vatSummary([issued]);
  assert.equal(summary.length, 1);
  const lineTotal = 10 * 8500;
  const firstDiscount = lineTotal * 10 / 100;
  const afterFirst = lineTotal - firstDiscount;
  const bulkDiscount = afterFirst * 2.5 / 100;
  const expectedBase = lineTotal - firstDiscount - bulkDiscount;
  assert.equal(summary[0].base, Math.round(expectedBase));
});

