test('lateFee scales with days overdue', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const fee10Days = lateFee(issued, '2026-10-25');
  const fee5Days = lateFee(issued, '2026-10-20');

  const expectedFee10 = Math.round(totals.total * 0.0004 * 10);
  const expectedFee5 = Math.round(totals.total * 0.0004 * 5);
  assert.equal(fee10Days, expectedFee10);
  assert.equal(fee5Days, expectedFee5);
  assert(fee10Days > fee5Days);
});

